//! Externally built kernels (for example compiler output) timed over
//! buffers.
//!
//! The table [`EXT_KERNELS`] is generated by gen/gen_ext.py (Buck genrule
//! `ext_table`): it includes the assembly in src/ext/, declares the
//! symbols, and lists every kernel with one of the setup functions below.
//! To add kernels by hand, include their assembly with
//! `core::arch::global_asm!(include_str!("ext/NAME.s"), options(raw));`
//! and add entries in the same form. Variable-trip kernels run for every
//! element count in [`EXT_COUNTS`] that is at least `min_n`; fixed-trip
//! kernels run only at `fixed_n`. Buffers are 16-byte aligned and, unless
//! `aligned_only`, also tested at +4 bytes. `setup` places the arguments:
//! `args` (r3..r8), float arguments in `fargs` (f1, f2).

use crate::harness::KernelFn;

/// Element counts (f32 elements): L1, L2 and main-memory sized.
pub const EXT_COUNTS: &[u32] = &[16, 1024, 65536];

/// Size of each buffer in bytes: the largest count of f32 or f64 elements,
/// slack for the +4 offset, and room for the `stagger` setting (up to
/// 32 KB per buffer).
pub const EXT_BUFFER_BYTES: usize = 65536 * 8 + 4096 + 2 * 32768;

pub struct ExtArgs {
    /// Addresses of buffers 0, 1 and 2 (aligned, or aligned + 4).
    pub bufs: [u32; 3],
    /// Element count.
    pub n: u32,
    /// r3..r8.
    pub args: [u32; 6],
    /// f1, f2.
    pub fargs: [f64; 2],
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Ret {
    None,
    /// The checksum includes r3.
    Int,
    /// The checksum includes f1.
    Float,
}

/// The source element type, not a reinterpretation of floating-point bits.
#[derive(Clone, Copy)]
pub enum Input {
    Float,
    PositiveFloat,
    FloatClamp,
    Int,
    Shift,
    Short,
    ShortClamp,
    Byte,
    Word,
}

impl Input {
    pub fn fill(self, bytes: &mut [u8], stream: usize) {
        match self {
            Self::Byte => {
                for (i, b) in bytes.iter_mut().enumerate() {
                    *b = ((i * 7 + stream * 31) % 256) as u8;
                }
            }
            Self::Short => {
                // Even 65536 products of two values in [-16, 16] fit i32.
                for (i, c) in bytes.chunks_exact_mut(2).enumerate() {
                    let x = ((i * 7 + stream * 3) % 33) as i16 - 16;
                    c.copy_from_slice(&x.to_be_bytes());
                }
            }
            Self::ShortClamp => {
                const VALUES: [i16; 11] = [-2000, -1001, -1000, -999, -1, 0, 1, 999, 1000, 1001, 2000];
                for (i, c) in bytes.chunks_exact_mut(2).enumerate() {
                    let x = VALUES[(i * 7 + stream * 3) % VALUES.len()];
                    c.copy_from_slice(&x.to_be_bytes());
                }
            }
            _ => {
                for (i, c) in bytes.chunks_exact_mut(4).enumerate() {
                    let x = ((i * 7 + stream * 3) % 17) as i32;
                    let bits = match self {
                        Self::Float => (x as f32 * 0.25 - 2.0).to_bits(),
                        // Dot-product rounding is exact for these positive dyadic products.
                        Self::PositiveFloat => ((x + 1) as f32 * 0.25).to_bits(),
                        Self::FloatClamp => {
                            const VALUES: [f32; 11] = [-256.0, -101.0, -100.0, -99.0, -1.0, 0.0, 1.0, 99.0, 100.0, 101.0, 256.0];
                            VALUES[(i * 7 + stream * 3) % VALUES.len()].to_bits()
                        }
                        // Sums, products, abs and reductions stay within i32.
                        Self::Int => (x - 8) as u32,
                        // Signed left shifts require nonnegative inputs.
                        Self::Shift => x as u32,
                        Self::Word => (i as u32).wrapping_mul(0x0102_0305) ^ (stream as u32 * 0x1234_5678),
                        Self::Short | Self::ShortClamp | Self::Byte => unreachable!(),
                    };
                    c.copy_from_slice(&bits.to_be_bytes());
                }
            }
        }
    }
}

/// Globals in source order: g_a, g_b, g_c, g_ia, g_ib, g_ic.
pub type Globals = fn() -> [u32; 6];

fn global_float(i: usize, stream: usize) -> f32 {
    // Positive dyadic values make every reduction exact and nonzero.
    (((i * 7 + stream * 3) % 17) + 1) as f32 * 0.25
}

fn global_int(i: usize, stream: usize) -> i32 {
    ((i * 7 + stream * 3) % 17 + 1) as i32
}

fn word(bytes: &[u8], i: usize) -> u32 {
    u32::from_be_bytes(bytes[4 * i..4 * i + 4].try_into().unwrap())
}

fn short(bytes: &[u8], i: usize) -> i16 {
    i16::from_be_bytes(bytes[2 * i..2 * i + 2].try_into().unwrap())
}

fn float(bytes: &[u8], i: usize) -> f32 {
    f32::from_bits(word(bytes, i))
}

fn put_word(bytes: &mut [u8], i: usize, value: u32) {
    bytes[4 * i..4 * i + 4].copy_from_slice(&value.to_be_bytes());
}

fn put_float(bytes: &mut [u8], i: usize, value: f32) {
    put_word(bytes, i, value.to_bits());
}

pub struct ExtKernel {
    pub name: &'static str,
    pub f: KernelFn,
    pub base: &'static str,
    /// Required designated reference, even when excluded by the name filter.
    pub reference: &'static str,
    pub input: Input,
    pub globals: Option<Globals>,
    pub setup: fn(&mut ExtArgs),
    pub ret: Ret,
    /// Skip the +4 offset (vector-typed sources need aligned pointers).
    pub aligned_only: bool,
    /// Smallest element count to run.
    pub min_n: u32,
    /// Actual work for kernels whose source ignores n.
    pub fixed_n: Option<u32>,
}

impl ExtKernel {
    pub fn reset_globals(&self) {
        let Some(globals) = self.globals else { return };
        for (j, addr) in globals().into_iter().enumerate() {
            for i in 0..1024 {
                let bits = match j {
                    0 | 1 => global_float(i, j).to_bits(),
                    2 => (-1000.0f32).to_bits(),
                    3 | 4 => global_int(i, j - 3) as u32,
                    _ => (-1000i32) as u32,
                };
                // SAFETY: generated globals are six distinct 1024-word arrays.
                unsafe { (addr as usize as *mut u32).add(i).write(bits) };
            }
        }
    }

    /// Independent scalar oracle also rejects a no-op SDK reference.
    pub fn check_globals(&self, result: f64) -> bool {
        let Some(globals) = self.globals else { return true };
        let mut dot = 0.0f32;
        for (j, addr) in globals().into_iter().enumerate() {
            for i in 0..1024 {
                let a = global_float(i, 0);
                let b = global_float(i, 1);
                let bits = match j {
                    0 | 1 => global_float(i, j).to_bits(),
                    2 => match self.base {
                        "k_g_add_f32" => (a + b).to_bits(),
                        "k_g_saxpy" => (3.0 * a + b).to_bits(),
                        _ => (-1000.0f32).to_bits(),
                    },
                    3 | 4 => global_int(i, j - 3) as u32,
                    _ if self.base == "k_g_add_i32" => (global_int(i, 0) + global_int(i, 1)) as u32,
                    _ => (-1000i32) as u32,
                };
                // SAFETY: as in reset_globals; every word is initialized.
                if unsafe { (addr as usize as *const u32).add(i).read() } != bits {
                    return false;
                }
                if j == 0 {
                    dot += a * b;
                }
            }
        }
        self.base != "k_g_dot" || result == dot as f64
    }

    /// Source-level oracle, never an external compiler-comparison function.
    /// Buffers include the initialized slack needed by stride/offset/FIR.
    /// None means missing semantics and is a failed check, not a fallback.
    pub fn scalar(&self, bufs: [&mut [u8]; 3], n: usize) -> Option<(u32, f64)> {
        let [y, a, b] = bufs;
        let mut int_result = 0i32;
        let mut float_result = 0.0f32;
        match self.base {
            "k_saxpy" | "k_saxpy_r" | "sp_saxpy_s" | "sp_saxpy_v" => {
                for i in 0..n {
                    let value = 3.0 * float(a, i) + float(y, i);
                    put_float(y, i, value);
                }
            }
            "k_scale_inplace" => {
                for i in 0..n {
                    let value = 3.0 * float(y, i);
                    put_float(y, i, value);
                }
            }
            "k_add_f32_r" | "k_add16_f32_r" => {
                for i in 0..n {
                    put_float(y, i, float(a, i) + float(b, i));
                }
            }
            "k_mul_f32_r" => {
                for i in 0..n {
                    put_float(y, i, float(a, i) * float(b, i));
                }
            }
            "k_sum_f32" => {
                for i in 0..n {
                    float_result += float(a, i);
                }
            }
            "k_dot_f32" | "sp_dot_s" | "sp_dot_v" => {
                for i in 0..n {
                    float_result += float(a, i) * float(b, i);
                }
            }
            "k_sum_i32" => {
                for i in 0..n {
                    int_result += word(a, i) as i32;
                }
            }
            "k_dot_i16" => {
                for i in 0..n {
                    int_result += short(a, i) as i32 * short(b, i) as i32;
                }
            }
            "k_max_f32" => {
                float_result = float(a, 0);
                for i in 1..n {
                    float_result = float_result.max(float(a, i));
                }
            }
            "k_add_i32" | "k_add_i32_r" => {
                for i in 0..n {
                    put_word(y, i, ((word(a, i) as i32) + (word(b, i) as i32)) as u32);
                }
            }
            "k_add_i16_r" => {
                for i in 0..n {
                    let value = short(a, i) + short(b, i);
                    y[2 * i..2 * i + 2].copy_from_slice(&value.to_be_bytes());
                }
            }
            "k_add_u8_r" | "k_avg_u8_r" | "k_addsat_u8_r" => {
                for i in 0..n {
                    let sum = a[i] as u16 + b[i] as u16;
                    y[i] = match self.base {
                        "k_add_u8_r" => sum as u8,
                        "k_avg_u8_r" => ((sum + 1) >> 1) as u8,
                        _ => sum.min(255) as u8,
                    };
                }
            }
            "k_and_u32_r" => {
                for i in 0..n {
                    put_word(y, i, word(a, i) & word(b, i));
                }
            }
            "k_shl_i32_r" => {
                for i in 0..n {
                    put_word(y, i, word(a, i) << 3);
                }
            }
            "k_mul_i32_r" => {
                for i in 0..n {
                    put_word(y, i, ((word(a, i) as i32) * (word(b, i) as i32)) as u32);
                }
            }
            "k_min_f32_r" => {
                for i in 0..n {
                    put_float(y, i, float(a, i).min(float(b, i)));
                }
            }
            "k_max_i32_r" => {
                for i in 0..n {
                    put_word(y, i, (word(a, i) as i32).max(word(b, i) as i32) as u32);
                }
            }
            "k_clamp_f32_r" => {
                for i in 0..n {
                    put_float(y, i, float(a, i).clamp(-100.0, 100.0));
                }
            }
            "k_clamp_i16_r" => {
                for i in 0..n {
                    let value = short(a, i).clamp(-1000, 1000);
                    y[2 * i..2 * i + 2].copy_from_slice(&value.to_be_bytes());
                }
            }
            "k_abs_f32_r" => {
                for i in 0..n {
                    put_float(y, i, float(a, i).abs());
                }
            }
            "k_abs_i32_r" => {
                for i in 0..n {
                    put_word(y, i, (word(a, i) as i32).abs() as u32);
                }
            }
            "k_f2i_r" => {
                for i in 0..n {
                    put_word(y, i, (float(a, i) as i32) as u32);
                }
            }
            "k_i2f_r" => {
                for i in 0..n {
                    put_float(y, i, (word(a, i) as i32) as f32);
                }
            }
            "k_u8_to_f32_r" | "sp_u8f_s" | "sp_u8f_v" => {
                for i in 0..n {
                    put_float(y, i, a[i] as f32 * (1.0f32 / 255.0));
                }
            }
            "k_mat4_vec4_r" | "sp_mat4_s" | "sp_mat4_v" | "sp_mat4_v8" | "sp_mat4_v16" | "sp_mat4_x" => {
                for i in (0..n).step_by(4) {
                    for row in 0..4 {
                        let value = float(a, row) * float(b, i)
                            + float(a, 4 + row) * float(b, i + 1)
                            + float(a, 8 + row) * float(b, i + 2)
                            + float(a, 12 + row) * float(b, i + 3);
                        put_float(y, i + row, value);
                    }
                }
            }
            "k_copy_u32_r" | "sp_copy_s" | "sp_copy_v" => y[..4 * n].copy_from_slice(&a[..4 * n]),
            "k_copy_u8" => y[..n].copy_from_slice(&a[..n]),
            "k_set_u32" => {
                for i in 0..n {
                    put_word(y, i, 0x1234_5678);
                }
            }
            "k_set_f32" => {
                for i in 0..n {
                    put_float(y, i, 3.0);
                }
            }
            "k_zero_u8" => y[..n].fill(0),
            "k_stride2_f32_r" => {
                for i in 0..n {
                    put_float(y, i, float(a, 2 * i) + float(a, 2 * i + 1));
                }
            }
            "k_gather_f32_r" => {
                for i in 0..n {
                    put_float(y, i, float(a, word(b, i) as usize));
                }
            }
            "k_offset1_f32_r" => {
                for i in 0..n {
                    put_float(y, i, float(a, i) + float(a, i + 1));
                }
            }
            "k_fir3_f32_r" => {
                for i in 0..n {
                    put_float(y, i, 0.25 * float(a, i) + 0.5 * float(a, i + 1) + 0.25 * float(a, i + 2));
                }
            }
            "k_prefix_f32" => {
                for i in 1..n {
                    let value = float(y, i) + float(y, i - 1);
                    put_float(y, i, value);
                }
            }
            "sp_bright_s" | "sp_bright_v" => {
                for i in 0..n {
                    y[i] = a[i].saturating_add(40);
                }
            }
            "sp_f2u8_s" | "sp_f2u8_v" => {
                for i in 0..n {
                    y[i] = (float(a, i) * 255.0 + 0.5).clamp(0.0, 255.0) as u8;
                }
            }
            "k_g_add_f32" | "k_g_saxpy" | "k_g_add_i32" => {}
            "k_g_dot" => {
                for i in 0..1024 {
                    float_result += global_float(i, 0) * global_float(i, 1);
                }
            }
            _ => return None,
        }
        Some((int_result as u32, float_result as f64))
    }
}

// Argument passing, observed in cl.exe, clang and rustc output: every
// argument takes the next GPR slot, floats included, and floats also go in
// f1, f2. So for (y, x, float a, n), n is in r6, not r5.

/// (y, x, float a, n): a in f1 (r5 slot), n in r6.
fn yxan(a: &mut ExtArgs) {
    a.args[0] = a.bufs[0];
    a.args[1] = a.bufs[1];
    a.args[3] = a.n;
    a.fargs[0] = 3.0;
}

/// (y, float a, n): a in f1 (r4 slot), n in r5.
fn yan(a: &mut ExtArgs) {
    a.args[0] = a.bufs[0];
    a.args[2] = a.n;
    a.fargs[0] = 3.0;
}

/// (c, a, b, n).
fn cabn(a: &mut ExtArgs) {
    a.args[0] = a.bufs[0];
    a.args[1] = a.bufs[1];
    a.args[2] = a.bufs[2];
    a.args[3] = a.n;
}

/// (y, x, n). Kernels that read past n (offset1: x[n], fir3: x[n+1],
/// stride2: x[0..2n)) stay inside EXT_BUFFER_BYTES.
fn yxn(a: &mut ExtArgs) {
    a.args[0] = a.bufs[0];
    a.args[1] = a.bufs[1];
    a.args[2] = a.n;
}

/// (x, n) -> value.
fn xn(a: &mut ExtArgs) {
    a.args[0] = a.bufs[1];
    a.args[1] = a.n;
}

/// (a, b, n) -> value.
fn abn(a: &mut ExtArgs) {
    a.args[0] = a.bufs[1];
    a.args[1] = a.bufs[2];
    a.args[2] = a.n;
}

/// (y, x, float lo, float hi, n): lo/hi in f1/f2 (r5/r6 slots), n in r7.
fn clamp(a: &mut ExtArgs) {
    a.args[0] = a.bufs[0];
    a.args[1] = a.bufs[1];
    a.args[4] = a.n;
    a.fargs = [-100.0, 100.0];
}

/// (out, m, in, n vec4 elements): n/4 keeps the f32 count.
fn mat4(a: &mut ExtArgs) {
    a.args[0] = a.bufs[0];
    a.args[1] = a.bufs[1];
    a.args[2] = a.bufs[2];
    a.args[3] = a.n / 4;
}

/// (y, x, idx, n): first writes idx[i] = (i * 7) % n into bufs[2].
fn gather(a: &mut ExtArgs) {
    let idx = a.bufs[2] as usize as *mut u32;
    for i in 0..a.n {
        // SAFETY: bufs[2] holds EXT_BUFFER_BYTES, more than 4 * n.
        unsafe { idx.add(i as usize).write((i * 7) % a.n) };
    }
    cabn(a);
}

/// (d, u32 v, n).
fn dvn(a: &mut ExtArgs) {
    a.args[0] = a.bufs[0];
    a.args[1] = 0x1234_5678;
    a.args[2] = a.n;
}

/// (d, n).
fn dn(a: &mut ExtArgs) {
    a.args[0] = a.bufs[0];
    a.args[1] = a.n;
}

/// The k_g_* kernels use their own 1024-element globals; fixed_n records
/// their actual work and aligned_only avoids duplicate buffer-offset rows.
fn none(_: &mut ExtArgs) {}

/// (float a) for k_g_saxpy.
fn g_a(a: &mut ExtArgs) {
    a.fargs[0] = 3.0;
}

include!("ext_table.rs");
